656	    if (wordsWritten <= 0) return;
657	
658	    const key = ProductivityMetrics.dateKey(date);
659	    const today = new Date();
660	    const yesterdayKey = ProductivityMetrics.dateKey(
661	      new Date(today.setDate(today.getDate() - 1))
662	    );
663	
664	    const existing = this._dailyCount.get(key) ?? 0;
665	    this._dailyCount.set(key, existing + wordsWritten);
