47	/**
48	 * Type guard that narrows Prisma errors to ClientKnownRequestError and
49	 * rethrows them as richer domain-level errors.
50	 */
51	function translatePrismaError(err: unknown): never {
52	  if (err instanceof Prisma.PrismaClientKnownRequestError) {
53	    switch (err.code) {
54	      case 'P2002':
55	        throw new UniqueConstraintError(
56	          err.meta?.target?.toString() || 'unknown',
57	        );
58	      case 'P2025':
59	        throw new NotFoundError(err.meta?.cause?.toString() || 'Record not found');
60	      default:
61	        throw new DomainError(err.message);
62	    }
63	  }
64	  throw err;
65	}
